 val a=listOf(Account("a","Cash","Espèces","Personnel",10000),Account("b","MoMo","MTN MoMo","Professionnel",2000)); val c=listOf(Category("c","Salaire","Entrée"),Category("d","Transport","Dépense")); val e=listOf(Entry("1","Entrée","a",null,"c",5000,0,"2026-11-24",""),Entry("2","Dépense","a",null,"d",1000,0,"2026-11-24",""),Entry("3","Transfert","a","b",null,3000,100,"2026-11-24",""));check(e.all{validEntry(it,a,c)});check(balances(a,e)==mapOf("a" to 10900L,"b" to 5000L));check(income(e)==5000L);check(expense(e)==1100L);check(!validEntry(e[2].copy(target="a"),a,c));check(!validEntry(e[1].copy(date="2026-02-30"),a,c));check(!validEntry(e[1].copy(category="c"),a,c));check(balances(a,e.filterNot{it.id=="3"})==mapOf("a" to 14000L,"b" to 2000L));val secret="données privées".toByteArray();val p="test-password-1234".toCharArray();val cipher=Backup.encrypt(secret,p);check(Backup.decrypt(cipher,p).contentEquals(secret));check(!cipher.contentEquals(Backup.encrypt(secret,p)));check(runCatching{Backup.decrypt(cipher,"incorrect password".toCharArray())}.isFailure);cipher[cipher.lastIndex]=(cipher.last().toInt() xor 1).toByte();check(runCatching{Backup.decrypt(cipher,p)}.isFailure);println("OK: ledger, edit/delete recompute, transfer fees, validation, backup encryption, wrong password, tampering")
